    fetched_at: now,
  };
  state.entity.market_cap_usd = marketCap;
  state.entity.market_cap_as_of = asOf;
} catch (e) {
  state.research.market_data = { confidence: 'N/A', error: String(e.message || e), fetched_at: now };
